<?php declare(strict_types=1); namespace Annam; $title='Razorpay payments'; ?>
<nav class="php-segments" aria-label="Payment mode"><?php foreach(['test'=>'Test mode','live'=>'Live mode'] as $key=>$label): ?><a class="o-btn <?= $mode===$key?'o-btn-primary':'' ?>" href="?mode=<?= e($key) ?>" <?= $mode===$key?'aria-current="page"':'' ?>><?= e($label) ?></a><?php endforeach; ?></nav><form class="o-form" method="post"><?= csrf() ?><section class="o-card"><h2><?= e(ucfirst($mode)) ?> account</h2><p>Saved secrets are never shown. Leave secret fields blank to keep them. Only one mode can be enabled for new payments.</p><label class="o-field">Razorpay Key ID<input name="key_id" value="<?= e($connection['key_id']) ?>" required maxlength="80" autocomplete="off"></label><?php foreach(['key_secret'=>'Key secret','webhook_secret'=>'Webhook secret'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($key) ?>" type="password" autocomplete="new-password" maxlength="4096"></label><?php endforeach; ?><label class="php-switch-row"><input class="php-toggle" role="switch" type="checkbox" name="enabled" value="1" <?= $connection['enabled']?'checked':'' ?>><span>Enable Razorpay for website checkout</span><b class="php-switch-state" aria-hidden="true"></b></label><button class="o-btn o-btn-primary">Save & verify connection</button></section></form><section class="o-card"><h2>Connect the Razorpay webhook</h2><p>Add this URL in the Razorpay dashboard’s <?= e($mode) ?> mode:</p><code><?= e(rtrim(getenv('APP_URL'),'/').'/platform/webhooks/'.$store->tenant['slug'].'/razorpay/'.$mode.'/') ?></code><p>Use the same webhook secret. Enable payment.captured, payment.failed, order.paid, refund.created, refund.processed and refund.failed. Enable automatic payment capture in Razorpay.</p></section>
